import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import java.util.*;
public class RobotPhase3 {
 static void particle(Game g){for(int i=0;i<1500;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.PARTICLES))if(g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void atom(Game g){for(int i=0;i<200;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.ATOMS))if(!u.id().equals("atom_keep")&&g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void dark(Game g){for(int i=0;i<100;i++){boolean bought=false;for(DarkUpgrade u:g.darkUpgrades())if(g.canBuyDark(u.id())){g.buyDark(u.id());bought=true;break;}if(!bought)break;}}
 public static void main(String[] args){Game g=new Game(new GameState(), Upgrades.DEFAULT, Automations.DEFAULT, DarkUpgrades.DEFAULT, idle.core.achievements.Achievements.DEFAULT, new Random(args.length>2?Long.parseLong(args[2]):42));g.start();int maxExplosions=args.length>0?Integer.parseInt(args[0]):3;int hours=args.length>1?Integer.parseInt(args[1]):8;double t=0;long fusions=0,synth=0;long start=System.nanoTime();for(int tick=0;tick<hours*3600&&g.state().explosions()<maxExplosions;tick++){g.tick(1);t++;particle(g);for(int i=0;i<5&&g.canFuse();i++){g.fuse();fusions++;atom(g);particle(g);}for(Automation a:g.automations())if(g.canBuyAutomation(a.id()))g.buyAutomation(a.id());for(Automation a:g.automations())if(g.canSpeedUpAutomation(a.id()))g.speedUpAutomation(a.id());atom(g);for(int i=0;i<15&&g.canSynthesize();i++){g.synthesize();synth++;}dark(g);if(g.canExplode()){System.out.printf(Locale.US,"EXPLOSION,%d,%.1f,%d,%d,%s,%d,%d%n",g.state().explosions()+1,t,g.discoveredElements(),g.achievementCount(),g.state().darkMatter(),fusions,synth);g.explode();}if(t%1800==0)System.out.printf(Locale.US,"CHECK,%.0f,%d,%d,%s,%d,%d%n",t,g.state().explosions(),g.discoveredElements(),g.state().darkMatter(),g.achievementCount(),g.state().completedChallenges().size());}System.out.printf(Locale.US,"END,%.1f,%d,%d,%s,%d,%d,wall=%.1f%n",t,g.state().explosions(),g.discoveredElements(),g.state().darkMatter(),g.achievementCount(),g.state().completedChallenges().size(),(System.nanoTime()-start)/1e9);}
}
